    /// <summary>
    /// Executes the posting logic for the Free text invoice.
    /// </summary>
    /// <param name = "_custInvoiceJour">
    /// The <c>CustInvoiceJour</c> table buffer.
    /// </param>
    /// <param name = "_ledgerVoucher">
    /// A LedgerVoucher used for posting.
    /// </param>
    /// <param name = "_creditNote">
    /// A boolean indicating whether or not it is a credit note.
    /// </param>
    /// <param name = "_numberSeq">
    /// A <c>NumberSeq</c> instance used to get the invoice ID.
    /// </param>
    protected void postCustInvoice(CustInvoiceJour _custInvoiceJour, LedgerVoucher _ledgerVoucher, boolean _creditNote, NumberSeq _numberSeq)
    { 
        next postCustInvoice(_custInvoiceJour, _ledgerVoucher, _creditNote, _numberSeq);

        this.METUpdateSupplierVolumetricRebateHeader();
    }

    /// <summary>
    /// Update the  ALM Supplier Volumetric Rebate Header with the FTI invoice id
    /// </summary>
    public void METUpdateSupplierVolumetricRebateHeader()
    {
        METALMSupplierVolumetricRebateHeader    METALMSupplierVolumetricRebateHeader;

        if(CustInvoiceTable.InvoiceId && CustInvoiceTable.PurchOrderFormNum)
        {
            ttsbegin;
            METALMSupplierVolumetricRebateHeader = METALMSupplierVolumetricRebateHeader::findByNumberCustLegalEntity(CustInvoiceTable.PurchOrderFormNum, CustInvoiceTable.dataAreaID ,true);
            
            if(METALMSupplierVolumetricRebateHeader 
            && METALMSupplierVolumetricRebateHeader.Status == METALMSupplierVolumetricRebateStatus::Processed
            && !METALMSupplierVolumetricRebateHeader.FreeTextInvoiceId)
            {
                changecompany(METALMSupplierVolumetricRebateHeader.DataAreaId)
                {
                    METALMSupplierVolumetricRebateHeader.FreeTextInvoiceId = CustInvoiceTable.InvoiceId;
                    METALMSupplierVolumetricRebateHeader.update();
                }
            }
            ttscommit;
        }
    }
